'use strict';
// Objects held by module-level bindings stay the same object when functions
// return them: identity holds and writes through either reference are seen.
const expected = { label: 'same' };
function wrapper() { return expected; }
function identity(value) { return value; }
const top = { inner: { n: 1 } };
function topInner() { return top.inner; }
function run() {
  const out = [];
  out.push(String(wrapper() === expected), String(identity(wrapper()) === expected));
  const t = topInner();
  t.n = 9;
  out.push(String(top.inner.n), String(topInner() === top.inner));
  const local = { inner: { n: 1 } };
  const getInner = () => local.inner;
  getInner().n = 5;
  out.push(String(local.inner.n));
  return out.join(' ');
}
module.exports = { run };
